/**
 * Persisted session registry. Each session lives at
 * `<stateRoot>/sessions/<sessionId>/` with a `session.json` record, an
 * `events.ndjson` log, and a `workspace/` directory. Continuation keys are
 * indexed in memory so channels can address sessions by their channel-local
 * token.
 *
 * The directory is the source of truth and the in-memory maps are a cache:
 * another process may create and update sessions behind this one's back (the
 * two version containers of a persistent deployment during a redeploy, or an
 * old process still exiting after a restart). A lookup that would otherwise
 * conclude "no such session" rescans the directory first, listings pick up
 * new directories, and a cached record is re-read when its file changed.
 */
import { randomBytes } from "node:crypto";
import { mkdir, readdir, readFile, rename, stat, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { isSafeSessionId } from "./auth.js";
import { isRecord } from "./is-record.js";
import { isV2DurableContinuationKey } from "./continuation-identity.js";
import { describeErrorCode } from "./describe-error.js";
function isSessionRecord(value) {
    return (isRecord(value) &&
        typeof value.sessionId === "string" &&
        typeof value.channelId === "string" &&
        (value.mode === "chat" || value.mode === "task") &&
        (value.continuationKey === null || typeof value.continuationKey === "string") &&
        (value.auth === null || isRecord(value.auth)) &&
        typeof value.turnCount === "number" &&
        typeof value.createdAt === "string" &&
        typeof value.updatedAt === "string");
}
export class SessionStore {
    constructor(sessionsDir) {
        this.sessionsDir = sessionsDir;
        this.cache = new Map();
        this.continuationIndex = new Map();
        /**
         * Identity of the `session.json` each cached record was read from, to
         * notice a peer's writes. Absent while our own `save` is still writing.
         */
        this.stamps = new Map();
    }
    sessionDir(sessionId) {
        if (!isSafeSessionId(sessionId)) {
            throw new Error(`Invalid session id: ${sessionId}`);
        }
        return join(this.sessionsDir, sessionId);
    }
    workspaceDir(sessionId) {
        return join(this.sessionDir(sessionId), "workspace");
    }
    eventFilePath(sessionId) {
        return join(this.sessionDir(sessionId), "events.ndjson");
    }
    recordPath(sessionId) {
        return join(this.sessionDir(sessionId), "session.json");
    }
    continuationKeyOf(channelId, key) {
        // v2 index is (agentId, cKey). This store is already per-agent, so drop
        // channelId for `cont:` / `evt:` keys. v1 stays `{channelId}\n{token}`.
        if (isV2DurableContinuationKey(key)) {
            return `\0v2\n${key}`;
        }
        return `${channelId}\n${key}`;
    }
    /**
     * Bring the cache in line with the directory: load records for session
     * directories not seen yet, drop records whose file is gone, and re-read
     * records whose file changed. Callers arriving while a scan is running
     * share it rather than queueing another.
     */
    scan() {
        if (this.scanning === undefined) {
            this.scanning = this.rescan().finally(() => {
                this.scanning = undefined;
            });
            this.hydrated ??= this.scanning;
        }
        return this.scanning;
    }
    async rescan() {
        let entries;
        try {
            entries = await readdir(this.sessionsDir);
        }
        catch (error) {
            if (describeErrorCode(error) !== "ENOENT") {
                // Unreadable for a reason other than absence: keep what we have
                // rather than forgetting sessions we cannot currently list.
                return;
            }
            // No directory means no sessions; the cache must not outlive it.
            entries = [];
        }
        const present = new Set();
        for (const sessionId of entries) {
            if (!isSafeSessionId(sessionId)) {
                continue;
            }
            present.add(sessionId);
            if (this.cache.has(sessionId)) {
                await this.refreshIfChanged(sessionId);
                continue;
            }
            await this.load(sessionId);
        }
        // The listing is a snapshot: a session saved since it was taken is not
        // in `present` but is on disk, so ask the file rather than the listing.
        for (const sessionId of [...this.cache.keys()]) {
            if (!present.has(sessionId)) {
                await this.refreshIfChanged(sessionId);
            }
        }
    }
    async ensureHydrated() {
        await (this.hydrated ?? this.scan());
    }
    async readRecord(sessionId) {
        if (!isSafeSessionId(sessionId)) {
            return undefined;
        }
        try {
            const raw = await readFile(this.recordPath(sessionId), "utf8");
            const parsed = JSON.parse(raw);
            return isSessionRecord(parsed) ? parsed : undefined;
        }
        catch {
            return undefined;
        }
    }
    /**
     * Identity of the file at `path`: inode plus mtime, so two renames within
     * one clock tick still read as different. Undefined when there is no
     * file; any other failure propagates.
     */
    async stampOf(path) {
        try {
            const info = await stat(path);
            return `${info.ino}:${info.mtimeMs}`;
        }
        catch (error) {
            if (describeErrorCode(error) === "ENOENT") {
                return undefined;
            }
            throw error;
        }
    }
    /**
     * Read a record from disk into the cache; returns it when present. The
     * stamp is taken before the read so a write landing in between leaves a
     * stale stamp, and the next lookup re-reads, rather than a fresh stamp on
     * stale bytes.
     */
    async load(sessionId) {
        if (!isSafeSessionId(sessionId)) {
            return undefined;
        }
        const stamp = await this.stampOf(this.recordPath(sessionId)).catch(() => undefined);
        if (stamp === undefined) {
            return undefined;
        }
        const record = await this.readRecord(sessionId);
        if (record === undefined) {
            return undefined;
        }
        this.remember(record, stamp);
        return record;
    }
    async refreshIfChanged(sessionId) {
        let stamp;
        try {
            stamp = await this.stampOf(this.recordPath(sessionId));
        }
        catch {
            // Unreadable for a reason other than absence: keep what we have.
            return;
        }
        if (stamp === undefined) {
            // No file for a record we never stamped is our own `save` still
            // writing it, not a deletion.
            if (this.stamps.has(sessionId)) {
                this.evict(sessionId);
            }
            return;
        }
        if (stamp !== this.stamps.get(sessionId)) {
            await this.load(sessionId);
        }
    }
    remember(record, stamp) {
        const previous = this.cache.get(record.sessionId);
        this.cache.set(record.sessionId, record);
        if (stamp !== undefined) {
            this.stamps.set(record.sessionId, stamp);
        }
        if (previous !== undefined &&
            previous.continuationKey !== null &&
            previous.continuationKey !== record.continuationKey) {
            this.unindex(previous);
        }
        this.indexRecord(record);
    }
    evict(sessionId) {
        const previous = this.cache.get(sessionId);
        this.cache.delete(sessionId);
        this.stamps.delete(sessionId);
        if (previous?.continuationKey != null) {
            this.unindex(previous);
        }
    }
    /**
     * Drop `record`'s claim on its continuation key. The index holds one
     * session per key; if another cached session still carries the same key
     * (a replacement created before the old one was re-keyed, or a peer's
     * write we learned of in this order), it takes the slot so the key does
     * not go dark until a restart.
     */
    unindex(record) {
        if (record.continuationKey === null) {
            return;
        }
        const indexKey = this.continuationKeyOf(record.channelId, record.continuationKey);
        if (this.continuationIndex.get(indexKey) !== record.sessionId) {
            return;
        }
        this.continuationIndex.delete(indexKey);
        for (const other of this.cache.values()) {
            if (other.sessionId !== record.sessionId &&
                other.continuationKey !== null &&
                this.continuationKeyOf(other.channelId, other.continuationKey) === indexKey) {
                this.continuationIndex.set(indexKey, other.sessionId);
                return;
            }
        }
    }
    indexRecord(record) {
        if (record.continuationKey !== null) {
            this.continuationIndex.set(this.continuationKeyOf(record.channelId, record.continuationKey), record.sessionId);
        }
    }
    async get(sessionId) {
        if (!isSafeSessionId(sessionId)) {
            return undefined;
        }
        if (this.cache.has(sessionId)) {
            await this.refreshIfChanged(sessionId);
            return this.cache.get(sessionId);
        }
        return this.load(sessionId);
    }
    async list() {
        await this.scan();
        return [...this.cache.values()].sort((a, b) => a.createdAt.localeCompare(b.createdAt));
    }
    async findByContinuation(channelId, key) {
        await this.ensureHydrated();
        const indexKey = this.continuationKeyOf(channelId, key);
        const lookup = async () => {
            const sessionId = this.continuationIndex.get(indexKey);
            if (sessionId === undefined) {
                return undefined;
            }
            const record = await this.get(sessionId);
            // `get` may have re-read the record and found its continuation moved,
            // or evicted it; either way this hit is stale.
            return record?.continuationKey === key ? record : undefined;
        };
        const found = await lookup();
        if (found !== undefined) {
            return found;
        }
        // A miss or a stale hit: another process may have created or re-keyed a
        // session since the last scan. Rescan once and retry.
        await this.scan();
        return lookup();
    }
    async save(record) {
        this.remember(record, undefined);
        const dir = this.sessionDir(record.sessionId);
        await mkdir(dir, { recursive: true });
        const finalPath = this.recordPath(record.sessionId);
        const tmpPath = `${finalPath}.${randomBytes(4).toString("hex")}.tmp`;
        await writeFile(tmpPath, `${JSON.stringify(record, null, 2)}\n`, "utf8");
        // Stamp the bytes we wrote, not whatever is at `finalPath` afterwards:
        // rename keeps inode and mtime, and a peer landing right behind us must
        // read as a change. Remember again so a concurrent read that loaded the
        // peer's earlier file does not leave the cache pointing at it.
        const stamp = await this.stampOf(tmpPath);
        await rename(tmpPath, finalPath);
        this.remember(record, stamp);
    }
}
